<article class="flight-result-card" data-flight-card data-flight-id="{{ $f->journey_key }}" data-passenger-count="{{ $filters['passenger_count'] }}">
    <div class="flight-card-main">
        <div class="flight-carrier"><span class="carrier-symbol" data-carrier="{{ $f->carrier_codes[0] }}" aria-hidden="true">{{ $f->carrier_codes[0] }}</span><div><strong title="{{ implode(' + ', $f->carrier_names) }}">{{ $f->carrier_names[0].(count($f->carrier_names)>1 ? ' +'.(count($f->carrier_names)-1).' hãng' : '') }}</strong><small>{{ $f->number }}</small>@if(($filters['trip_type'] ?? 'ONE_WAY')==='ROUND_TRIP')<span class="round-trip-badge">Khứ hồi</span>@endif</div></div>
        <div class="flight-timeline"><div><strong>{{ $f->departure_time }}</strong><span>{{ $f->origin }}</span></div><div class="flight-route-duration"><span>{{ intdiv($f->duration_minutes,60) }}h {{ str_pad((string)($f->duration_minutes%60),2,'0',STR_PAD_LEFT) }}m</span><div class="flight-route-line"><i></i><span>✈</span></div><small>{{ $f->stop_count ? $f->stop_count.' điểm dừng' : 'Bay thẳng' }}</small>@if($f->via)<small class="flight-via">{{ implode(' · ',$f->via) }}</small>@endif</div><div><strong>{{ $f->arrival_time }}@if($f->arrival_day_offset>0)<sup>+{{ $f->arrival_day_offset }}</sup>@endif</strong><span>{{ $f->destination }}</span></div></div>
        <div class="flight-card-price"><span class="price" data-flight-price>{{ $ui::money($f->price) }}</span><small>/ hành khách / {{ $outboundQuote ? 'lượt về' : 'lượt đi' }}</small><span class="flight-stock {{ $f->remaining<$filters['passenger_count'] ? 'is-sold-out' : '' }}" data-flight-stock>{{ $f->remaining>0 ? 'Còn '.$f->remaining.' chỗ' : 'Hết chỗ' }}</span></div>
    </div>
    @if($f->stop_count)<details class="flight-connection-details"><summary>Xem lịch trình và điểm dừng</summary>@if($f->self_transfer)<p>Tự nối chuyến giữa các hãng; kiểm tra việc nhận lại hành lý và làm thủ tục cho chuyến tiếp theo.</p>@endif @foreach($f->legs as $index=>$leg)<div><strong>{{ \App\Modules\Flights\Carrier::name($leg->carrier_code) }} · {{ $leg->number }} · {{ $leg->origin }} → {{ $leg->destination }}</strong><span>{{ $leg->departure_time }}–{{ $leg->arrival_time }} · {{ $leg->aircraft_type }}</span></div>@if($index<count($f->legs)-1)<p>Chờ nối chuyến tại {{ $airportsByCode[$leg->destination]->city ?? $leg->destination }} ({{ $leg->destination }}): {{ (int)\Carbon\Carbon::parse($leg->arrival)->diffInMinutes(\Carbon\Carbon::parse($f->legs[$index+1]->departure)) }} phút</p>@endif @endforeach</details>@endif
    <div class="flight-card-bottom"><div class="flight-card-meta"><span>{{ \Carbon\Carbon::parse($f->departure_day)->format('d/m/Y') }}</span><span>{{ $outboundQuote ? 'Lượt về' : 'Lượt đi' }}</span>@if($f->is_demo)<span>Lịch bay mô phỏng</span>@endif @if($f->self_transfer)<span>Tự nối chuyến</span>@endif @if($f->status==='DELAYED')<span class="flight-delay">Chậm giờ</span>@elseif($f->status==='BOARDING')<span class="flight-boarding">Đang đón khách</span>@endif</div>
        <form method="get" action="/trip/select" class="flight-booking-controls" data-trip-choice>
            <input type="hidden" name="flights" value="{{ implode(',',array_column($f->legs,'id')) }}"><input type="hidden" name="passenger_count" value="{{ $filters['passenger_count'] }}"><input type="hidden" name="trip_type" value="{{ $filters['trip_type'] ?? 'ONE_WAY' }}"><input type="hidden" name="return_date" value="{{ $filters['return_date'] ?? '' }}">@if(!empty($filters['outbound']))<input type="hidden" name="outbound" value="{{ $filters['outbound'] }}">@endif
            <label class="visually-hidden" for="fare-{{ $f->journey_key }}">Hạng giá {{ $f->number }}</label><select class="form-select" name="fare_class" id="fare-{{ $f->journey_key }}" data-flight-fare>@foreach($f->fares as $fare)<option value="{{ $fare->code }}" data-price="{{ $fare->price }}" data-remaining="{{ $fare->remaining }}" @selected($f->selected_fare===$fare->code) @disabled($fare->remaining<$filters['passenger_count'])>{{ $fare->name }} · {{ $ui::money($fare->price) }}</option>@endforeach</select><button class="btn btn-primary" data-trip-choose @disabled($f->remaining<$filters['passenger_count'])>Chọn</button>
        </form>
    </div>
</article>
